import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv with empty invoice list', () => {
  const result = exportCsv([]);

  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines.length, 2); // Header + empty line at end
});

test('exportCsv includes header', () => {
  const result = exportCsv([]);

  assert(result.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv with single invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  const lines = result.split('\n');
  assert.equal(lines.length, 3); // Header + 1 invoice + empty line
  assert(lines[1].includes(issued.number));
  assert(lines[1].includes('Northwind Studio')); // C-001 is Northwind Studio
});

test('exportCsv includes invoice number', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.includes(issued.number));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.includes('Pixel Cats')); // C-002 is Pixel Cats
});

test('exportCsv includes dates', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.includes('2025-02-15'));
  assert(result.includes('2025-03-17')); // Due date for NET30
});

test('exportCsv includes status', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.includes('issued'));
});

test('exportCsv formats amounts as euros with 2 decimals', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  // Amount should be like 50.00 (100 * 0.50 EUR)
  assert(result.includes('50.00'));
});

test('exportCsv uses dot as decimal separator', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  // Should have dot, not comma
  const lines = result.split('\n');
  const dataLine = lines[1];
  // Check that amounts have dots
  const parts = dataLine.split(',');
  // Last parts should be amounts with dots
  assert(parts[parts.length - 1].includes('.') || parts[parts.length - 1] === '');
});

test('exportCsv with multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2025-0001']).value;

  const result = exportCsv([issued1, issued2]);

  const lines = result.split('\n');
  assert.equal(lines.length, 4); // Header + 2 invoices + empty line
  assert(lines[1].includes('Northwind Studio'));
  assert(lines[2].includes('Pixel Cats'));
});

test('exportCsv quotes fields with commas', () => {
  // Get customer with name that has comma
  // Looking at the test data, we need to check if any customer has comma
  // For now, let's create a test scenario
  const inv = createInvoice({
    customerId: 'C-003', // Kite & Co
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.includes('Kite & Co'));
});

test('exportCsv quotes fields with double quotes', () => {
  // This would require a customer name with quotes, which we don't have in test data
  // But we can test the quoting logic indirectly
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  // Should not have unescaped quotes
  assert(!result.includes('""'));
});

test('exportCsv with partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued).value;
  const partial = recordPayment(issued, {
    amount: Math.floor(totals.total / 2),
    date: '2025-02-16',
  }).value;

  const result = exportCsv([partial]);

  assert(result.includes('partially_paid'));
  // Due should be half the total
  const lines = result.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const due = parseFloat(parts[parts.length - 1]);
  const total = parseFloat(parts[parts.length - 2]);
  assert(due < total);
  assert(due > 0);
});

test('exportCsv with paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued).value;
  const paid = recordPayment(issued, {
    amount: totals.total,
    date: '2025-02-16',
  }).value;

  const result = exportCsv([paid]);

  assert(result.includes('paid'));
  // Due should be 0
  const lines = result.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const due = parseFloat(parts[parts.length - 1]);
  assert.equal(due, 0);
});

test('exportCsv with discount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  const lines = result.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const discount = parseFloat(parts[6]);
  assert(discount > 0);
});

test('exportCsv with VAT', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  const lines = result.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const vat = parseFloat(parts[7]);
  assert(vat > 0);
});

test('exportCsv lines end with newline', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(result.endsWith('\n'));
  // Each line should end with \n
  const lines = result.split('\n');
  // All lines except the last (which is empty) should be valid CSV lines
  assert(lines[0].includes('number,customer'));
  assert(lines[1].length > 0);
});

test('exportCsv with invoice with tier discount', () => {
  const inv = createInvoice({
    customerId: 'C-001', // gold tier: 5% discount
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  const lines = result.split('\n');
  const dataLine = lines[1];
  const parts = dataLine.split(',');
  const discount = parseFloat(parts[6]);
  assert(discount > 0); // Should have 5% tier discount
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  const existingNumbers = [];

  for (let i = 1; i <= 3; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: `2025-02-${10 + i}`,
      lines: [{ sku: 'DEV-HOUR', qty: i }],
    }).value;

    const issued = issueInvoice(inv, existingNumbers).value;
    existingNumbers.push(issued.number);
    invoices.push(issued);
  }

  const result = exportCsv(invoices);

  const lines = result.split('\n');
  // Verify order is preserved by checking invoice numbers
  assert(lines[1].includes(invoices[0].number));
  assert(lines[2].includes(invoices[1].number));
  assert(lines[3].includes(invoices[2].number));
});

test('exportCsv with large amount', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10000 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  // Should format large amounts correctly (no thousands separator)
  assert(result.includes('950000.00')); // 10000 * 95 EUR
});

test('exportCsv amount precision', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'STICKER', qty: 333 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  // 333 * 0.50 = 166.50
  assert(result.includes('166.50'));
});

test('exportCsv with missing customer', () => {
  // Create an invoice with an invalid customer ID
  // This is tricky since createInvoice validates customers
  // We'll create a valid invoice and then manually change the customer ID
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  // Manually change customer ID to invalid one
  issued.customerId = 'C-999';

  const result = exportCsv([issued]);

  // Should still export, just without customer name
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert(lines[1].includes(issued.number));
});

test('exportCsv returns a string', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = exportCsv([issued]);

  assert(typeof result === 'string');
});

